public static void populateConfigurationXMLWithPinnableValues(XmlElement _configNode, TFMPage _page)
{
    TFMPinnableValues   pinValues;
    XmlElement          pinnableRegistrationValues = _configNode.ownerDocument().createElement('pinnableRegistrationValues');

    while select pinValues where pinValues.PageID == _page.parmId()
    {
        TFMPinnableValues::AddFormatElements(pinValues,pinnableRegistrationValues);
    }
    if (pinnableRegistrationValues.hasChildNodes())
    {
        _configNode.appendChild(pinnableRegistrationValues);
    }
}

public static void AddFormatElements(TFMPinnableValues _pinValue, XmlElement _pinnableRegistrationValues)
{
    TFMGS1AISetup GS1Setup;

    if (_pinValue.RegularExpression)
    {
        TFMPinnableValues::AddFormatElement(_pinnableRegistrationValues, 'pinnableByFormat', '', _pinValue.RegularExpression, _pinValue.Name, _pinValue.DisplayName,_pinValue.Icon);            
    }
    if (_pinValue.GS1Name)
    {
        while select GS1Setup where GS1Setup.Name == _pinValue.GS1Name
        {
            TFMPinnableValues::AddFormatElement(_pinnableRegistrationValues, 'pinnableByAi', int2Str(GS1Setup.GS1AI), '', _pinValue.Name, _pinValue.DisplayName,_pinValue.Icon);
        }
    }
}

public static void AddFormatElement(XmlElement _pinnableRegistrationValues, Name _elementName, Name _attrGS1AI, TFMRegularExpression _format, Name _attrName, TFMLocalizedStringEDT _attrDisplayName, TFMImageName _attrIcon)
{
    XmlElement          pinByElement = _pinnableRegistrationValues.ownerDocument().createElement(_elementName);
    pinByElement.setAttribute('name', _attrName);
    pinByElement.setAttribute('displayLabel',_attrDisplayName);        
    pinByElement.setAttribute('icon',_attrIcon);
    if (_format)
    {
        pinByElement.setAttribute('format', _format);
    }
    else if (_attrGS1AI)
    {
        pinByElement.setAttribute('eanAi',_attrGS1AI);
    }
    _pinnableRegistrationValues.appendChild(pinByElement);
}
